import json
with open('artifacts/_project/data/fpr_transparency_all_seeds.json') as f:
    data = json.load(f)

counts = {'threshold': 0, 'ty': 0, 'naive': 0}
total = 0

for seed_data in data['seeds']:
    for pair in seed_data['pairs']:
        total += 1
        if pair.get('threshold_onset_sig', False):
            counts['threshold'] += 1
        if pair.get('ty_granger_sig', False):
            counts['ty'] += 1
        if pair.get('naive_xcorr_sig', False):
            counts['naive'] += 1

for method, count in counts.items():
    print(f'{method}: {count}/{total} = {count/total*100:.1f}%')
